{{- with .Values.gnb }}
{{- if .enabled }}
apiVersion: v1
kind: ConfigMap
metadata:
  name: {{ .configmap.name }}
  labels:
    app: {{ $.Values.projectName }}
    component: {{ .name }}
data:
  gnb-config.yaml: |

    {{- .configuration | nindent 4 }}

{{- if $.Values.global.gnb.multus.enabled }}
    linkIp: 0.0.0.0   # gNB's local IP address for Radio Link Simulation (listen on all interfaces for UE connection)
{{- if .amf.service.ngap.enabled }}
    ngapIp: 0.0.0.0
{{- else }}
    ngapIp: {{ .n2if.ipAddress }} 
{{- end }}
    gtpIp: {{ .n3if.ipAddress }}    # gNB's local IP address for N3 Interface

    # List of AMF address information
    amfConfigs:
      - address: {{ .amf.n2if.ipAddress }}
        port: {{ .amf.n2if.port }}
{{- else }}
    linkIp: GNB_POD_IP   # gNB's local IP address for Radio Link Simulation
    ngapIp: GNB_POD_IP   # gNB's local IP address for N2 Interface
    gtpIp: GNB_POD_IP    # gNB's local IP address for N3 Interface

    # List of AMF address information
    amfConfigs:
      - address: {{ $.Values.global.free5gcReleaseName }}-{{ .amf.n2if.serviceName }}
        port: {{ .amf.n2if.port }}
{{- end }}

  wrapper.sh: |
    #!/bin/sh
    set -e

{{- if $.Values.global.gnb.multus.enabled }}
    # Multus mode: Static IPs are configured, run gNB directly
    echo "[gNB wrapper] Multus mode enabled - using static IP configuration"
    exec ./nr-gnb -c /ueransim/config/gnb-config.yaml
{{- else }}
    # Dynamic Pod IP mode
    # Get Pod IP dynamically
    POD_IP=$(hostname -i | awk '{print $1}')
    echo "[gNB wrapper] Pod IP detected: $POD_IP"

    # Copy config to writable location
    cp /ueransim/config/gnb-config.yaml /tmp/gnb-config.yaml

    # Replace POD_IP placeholder
    sed -i "s/GNB_POD_IP/$POD_IP/g" /tmp/gnb-config.yaml

    echo "[gNB wrapper] Configuration prepared:"
    cat /tmp/gnb-config.yaml | grep -E "linkIp|ngapIp|gtpIp"

    # Execute gNB
    exec ./nr-gnb -c /tmp/gnb-config.yaml
{{- end }}

{{- end }}
{{- end }}
{{- with .Values.gnb }}
{{- if and .enabled }}
apiVersion: apps/v1
kind: Deployment
metadata:
  name: {{ include "ueransim.fullname" $ }}-{{ .name }}
  labels:
    {{- include "ueransim.labels" $ | nindent 4 }}
    app: {{ $.Values.projectName }}
    component: {{ .name }}
spec:
  selector:
    matchLabels:
      {{- include "ueransim.selectorLabels" $ | nindent 6 }}
      app: {{ $.Values.projectName }}
      component: {{ .name }}
  replicas: {{ .replicaCount }}
  template:
    metadata:
      labels:
        {{- include "ueransim.selectorLabels" $ | nindent 8 }}
        app: {{ $.Values.projectName }}
        component: {{ .name }}
      annotations:
        {{- include "ueransim.gnbAnnotations" $ | nindent 8 }}
        {{- if and $.Values.global.gnb.multus.enabled (or $.Values.global.gnb.multus.n2network.enabled $.Values.global.gnb.multus.n3network.enabled) }}
        k8s.v1.cni.cncf.io/networks: '[
        {{- if $.Values.global.gnb.multus.n2network.enabled }}
            { "name": "{{ $.Values.global.gnb.multus.n2network.name }}-{{ include "ueransim.fullname" $ }}",
              "interface": "n2",
              "ips": [ "{{ .n2if.ipAddress }}/{{ $.Values.global.gnb.multus.n2network.cidr }}" ],
              "gateway": [ "{{ $.Values.global.gnb.multus.n2network.gatewayIP }}" ]
            },
        {{- end }}
            { "name": "{{ $.Values.global.gnb.multus.n3network.name }}-{{ include "ueransim.fullname" $ }}",
              "interface": "n3",
              "ips": [ "{{ .n3if.ipAddress }}/{{ $.Values.global.gnb.multus.n3network.cidr }}" ],
              "gateway": [ "{{ $.Values.global.gnb.multus.n3network.gatewayIP }}" ]
            }
            ]'
        {{- end }}
    spec:
      imagePullSecrets:
        {{- toYaml .imagePullSecrets | nindent 8 }}
      securityContext:
        {{- toYaml .podSecurityContext | nindent 8 }}
      initContainers:
      - name: wait-amf
        {{- with $.Values.initcontainers.sctp_test }}
        image: {{ .image }}:{{ .tag }}
        {{- end }}
{{- if $.Values.global.gnb.multus.enabled }}
        command: ["sh", "-c", "until sctp_test -s -H 0.0.0.0 -P 25000 -h {{ .amf.n2if.ipAddress }} -p {{ .amf.n2if.port }}; do echo waiting for the AMF; sleep 2; done;"]
{{- else }}
        command: ["sh", "-c", "until sctp_test -s -H 0.0.0.0 -P 25000 -h {{ $.Values.global.free5gcReleaseName }}-{{ .amf.n2if.serviceName }} -p {{ .amf.n2if.port }}; do echo waiting for the AMF; sleep 2; done;"]
{{- end }}
      containers:
      - image: {{ .image.name }}:{{ .image.tag | default $.Chart.AppVersion }}
        name: {{ .name }}
        ports:
        - name: gnb-ue
          containerPort: {{ .service.port }}
          protocol: {{ .service.protocol }}
        securityContext:
          capabilities:
            add: ["NET_ADMIN"]
{{- if $.Values.global.gnb.multus.enabled }}
        command: ["./nr-gnb"]
        args: ["-c", "{{ .volume.mount }}/gnb-config.yaml"]
{{- else }}
        command: ["/bin/sh", "-c"]
        args: ["cp /ueransim/config/wrapper.sh /tmp/wrapper.sh && chmod +x /tmp/wrapper.sh && /tmp/wrapper.sh"]
{{- end }}  
        volumeMounts:
        - mountPath: {{ .volume.mount }}
          name: {{ .volume.name }}
        resources:
            {{- toYaml .resources | nindent 12 }}
      dnsPolicy: ClusterFirst
      restartPolicy: Always
      nodeSelector:
        {{- toYaml .nodeSelector | nindent 8 }}
      affinity:
        {{- toYaml .affinity | nindent 8 }}
      tolerations:
        {{- toYaml .tolerations | nindent 8 }}

      volumes:
      - name: {{ .volume.name }}
        configMap:
          name: {{ .configmap.name }}
{{- end }}
{{- end }}

