  upSecurity: upSecurityDTOSchema.optional(), 
})

interface DnnConfigurationDTO {
  default5qi: number;
  sessionAmbr: AmbrDTO;
  enableStaticIpv4Address: boolean;
  staticIpv4Address?: string;
